import{_ as o,a0 as d,w as p,s as r,I as i,x as e,a1 as t,A as l,ao as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"Linux 中的模糊文件搜索 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 中的模糊文件搜索 | LCTT (202306) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 中的模糊文件搜索 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 中的模糊文件搜索 | LCTT (202306) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202306/20230611.0 ⭐️⭐️ Fuzzy File Search in Linux","title":"Linux 中的模糊文件搜索","tag":"202306","desc":""},"relativePath":"202306/20230611.0 ⭐️⭐️ Fuzzy File Search in Linux.md","filePath":"[post].md"}'),h={name:"202306/20230611.0 ⭐️⭐️ Fuzzy File Search in Linux.md"};function f(c,s,g,b,k,u){const a=d("Link");return p(),r("div",null,[s[26]||(s[26]=i("h1",{id:"linux-中的模糊文件搜索",tabindex:"-1"},[e("Linux 中的模糊文件搜索 "),i("a",{class:"header-anchor",href:"#linux-中的模糊文件搜索","aria-label":"Permalink to “Linux 中的模糊文件搜索”"},"​")],-1)),s[27]||(s[27]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202306/24/001013mc7chh224c7uls8h.jpg",alt:""})],-1)),s[28]||(s[28]=i("blockquote",null,[i("p",null,"像 fzf 和 fzy 这样的现代工具将 Linux 终端中的文件搜索提升到了一个新的水平。")],-1)),i("p",null,[s[2]||(s[2]=e("在 Linux 命令行中，如何 ",-1)),t(a,{href:"https://learnubuntu.com:443/find-files/"},{default:l(()=>[...s[0]||(s[0]=[e("搜索文件",-1)])]),_:1}),s[3]||(s[3]=e("？你可以使用 ",-1)),t(a,{href:"https://linuxhandbook.com:443/find-command-examples/"},{default:l(()=>[...s[1]||(s[1]=[e("find 命令",-1)])]),_:1}),s[4]||(s[4]=e("。这是标准答案，没有问题。",-1))]),s[29]||(s[29]=n('<p>通常，你键入带有搜索参数的命令，按回车键，然后它会显示搜索结果。</p><p>你可以通过模糊搜索来提升终端中的文件搜索体验。</p><p>模糊搜索是一种近似搜索算法或技术。在这种搜索中，通过名称搜索指定位置的文件，并实时显示结果给用户。</p><p>模糊搜索在网络搜索引擎中很受欢迎，用户开始输入术语后，它会开始显示与该术语相关的结果。</p><p>在本文中，我将讨论两个命令行工具，它们可以让你在 Linux 中执行模糊搜索：</p><ul><li><code>fzf</code>：模糊查找工具</li><li><code>fzy</code>：模糊选择工具</li></ul><h3 id="fzf-linux-中的模糊查找工具" tabindex="-1">fzf：Linux 中的模糊查找工具 <a class="header-anchor" href="#fzf-linux-中的模糊查找工具" aria-label="Permalink to “fzf：Linux 中的模糊查找工具”">​</a></h3><p><code>fzf</code> 是一款可用于 Linux 的模糊搜索工具，你可以通过它进行交互式文件搜索。</p><p>在 Ubuntu 中安装 <code>fzf</code>，打开终端并运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install fzf</span></span></code></pre></div><p>虽然 <code>fzf</code> 本身可以正常工作，但最好与其他工具配合使用，以充分发挥其功能。</p><h4 id="使用-fzf" tabindex="-1">使用 fzf <a class="header-anchor" href="#使用-fzf" aria-label="Permalink to “使用 fzf”">​</a></h4><p>打开终端并运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fzf</span></span></code></pre></div><p>这将打开一个 <code>fzf</code> 提示符，在当前工作目录中搜索文件。</p><p><img src="https://itsfoss.com/content/images/2023/06/fzf-default.svg" alt="在终端中运行 fzf 命令"></p><h5 id="为-fzf-应用边框" tabindex="-1">为 fzf 应用边框 <a class="header-anchor" href="#为-fzf-应用边框" aria-label="Permalink to “为 fzf 应用边框”">​</a></h5><p>你可以使用 <code>--border</code> 选项为 <code>fzf</code> 应用边框，有多种边框可用，如 <code>rounded</code>（圆角）、<code>sharp</code>（尖角）等。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fzf --border=rounded</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/06/fzf-border.svg" alt="运行带有边框选项设置为 rounded 和 sharp 的 fzf 命令"></p><h5 id="应用背景和前景颜色" tabindex="-1">应用背景和前景颜色 <a class="header-anchor" href="#应用背景和前景颜色" aria-label="Permalink to “应用背景和前景颜色”">​</a></h5><p>使用颜色属性，你可以为 <code>fzf</code> 设置 ANSI 颜色，可以作为背景、前景或两者都设置。</p><p><img src="https://itsfoss.com/content/images/2023/06/fzf-colored.svg" alt="为 fzf 应用颜色，用户指定了颜色"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fzf --color=&quot;bg:black,fg:yellow&quot;</span></span></code></pre></div><p>你可以串联这些选项，使 <code>fzf</code> 在视觉上更加美观。</p><p>现在，让我展示一些 <code>fzf</code> 模糊搜索的实际用法。</p><h4 id="使用-fzf-在-bash-历史中进行搜索" tabindex="-1">使用 fzf 在 Bash 历史中进行搜索 <a class="header-anchor" href="#使用-fzf-在-bash-历史中进行搜索" aria-label="Permalink to “使用 fzf 在 Bash 历史中进行搜索”">​</a></h4><p>当然，Bash 历史记录中有 <code>CTRL+R</code> 的反向搜索功能。但如果你想使用 <code>fzf</code> 来获得更好的外观，可以运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>history | fzf</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/06/search-within-bash-history.svg" alt="使用 fzf 模糊搜索在 bash 历史中进行搜索"></p><h4 id="使用-fzf-结合-tree-命令" tabindex="-1">使用 fzf 结合 tree 命令 <a class="header-anchor" href="#使用-fzf-结合-tree-命令" aria-label="Permalink to “使用 fzf 结合 tree 命令”">​</a></h4>',31)),i("p",null,[t(a,{href:"https://linuxhandbook.com:443/tree-command/"},{default:l(()=>[...s[5]||(s[5]=[e("tree 命令",-1)])]),_:1}),s[6]||(s[6]=e(" 会列出文件和目录，并显示它们的层级关系。",-1))]),s[30]||(s[30]=n('<p>使用 <code>fzf</code> 结合 <code>tree</code> 命令可以帮助你找到特定文件的绝对路径。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tree -afR /home/$USER | fzf</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/06/tree-afr.svg" alt="运行 Tree 命令并将输出传递给模糊搜索"></p><blockquote><p>💡 上述命令会调用 <code>tree</code> 并以递归方式列出包括隐藏文件在内的所有文件（<code>-a</code>）。同时，<code>-f</code> 选项告诉 <code>tree</code> 列出完整路径。</p></blockquote><h4 id="在-fzf-中预览文件" tabindex="-1">在 fzf 中预览文件 <a class="header-anchor" href="#在-fzf-中预览文件" aria-label="Permalink to “在 fzf 中预览文件”">​</a></h4><p>有时，如果你可以获得你搜索的文件的小型预览，那会很有帮助。</p><p>幸运的是，<code>fzf</code> 提供了一个预览选项。你可以使用 <code>--preview</code> 来访问它。我在这里使用 <code>find</code> 命令使其更加有用。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /home/$USER -type f | fzf --preview &#39;less {}&#39;</span></span></code></pre></div><p>在这里，当你滚动浏览结果时，它将使用 <code>less</code> 显示文本文件。</p><blockquote><p>🚧 如果你使用其他命令如 <code>ls</code> 等，请不要使用 <code>-l</code> 等选项，因为这将显示额外的详细信息（文件权限）。这些额外的详细信息会破坏 <code>fzf</code> 预览所需的格式。在使用预览功能时，输入到 <code>fzf</code> 的应该只是文件名。</p></blockquote><p>如果你已安装了 <code>bat</code>，也可以使用它来预览文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /home/$USER -type f | fzf --preview &#39;bat --color always {}&#39;</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/06/bashrc-preview-in-fzf.png" alt="使用 bat 作为 FZF 预览功能的文本查看器"></p><p>对于 Ubuntu 用户，可以使用 <code>batcat</code> 来调用 <code>bat</code>。因此运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /home/$USER -type f | fzf --preview &#39;batcat --color always {}&#39;</span></span></code></pre></div>',15)),i("blockquote",null,[i("p",null,[s[8]||(s[8]=e("💡 ",-1)),t(a,{href:"https://linuxhandbook.com:443/linux-alias-command/"},{default:l(()=>[...s[7]||(s[7]=[e("为这些命令创建别名",-1)])]),_:1}),s[9]||(s[9]=e("，这样你就不需要反复输入它们。",-1))])]),s[31]||(s[31]=n(`<h4 id="从任何地方使用-fzf-进入任何目录-高级技巧" tabindex="-1">从任何地方使用 fzf 进入任何目录（高级技巧） <a class="header-anchor" href="#从任何地方使用-fzf-进入任何目录-高级技巧" aria-label="Permalink to “从任何地方使用 fzf 进入任何目录（高级技巧）”">​</a></h4><p>这比以前要复杂一些。在这里，你不能直接将 <code>fzf</code> 和 <code>cd</code> 连接在一起，因为它们是不同的进程。</p><p>你可以创建一个别名并使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd $(find /home/$USER -type d | fzf)</span></span></code></pre></div><p>或者，你可以按照下面解释的方法进行操作。</p><p>为此，你可能需要在 <code>bashrc</code> 中添加一个函数。让我将这个函数称为 <code>finder</code>。现在请添加以下行到你的 <code>bashrc</code> 中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>finder() {</span></span>
<span class="line"><span>  local dir</span></span>
<span class="line"><span>  dir=$(find required/location/to/search/and/enter -type d | fzf)</span></span>
<span class="line"><span>  if [[ -n &quot;$dir&quot; ]]; then</span></span>
<span class="line"><span>    cd &quot;$dir&quot; || return</span></span>
<span class="line"><span>  fi</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,7)),i("p",null,[s[11]||(s[11]=e("现在，你应该 ",-1)),t(a,{href:"https://itsfoss.com/change-directories/"},{default:l(()=>[...s[10]||(s[10]=[e("输入路径",-1)])]),_:1}),s[12]||(s[12]=e("，其中包含你要搜索并进入的目录。",-1))]),s[32]||(s[32]=n('<p>例如，我已经使用 <code>/home/$USER</code> 替换了该部分，表示我要从任何位置进入我的主目录中的任何目录。</p><p>保存你的 <code>bashrc</code> 文件后，要么重启终端，要么运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>source ~/.bashrc</span></span></code></pre></div><p>之后，你可以在终端上运行 <code>finder</code> 命令，一旦找到要进入的目录，按回车键即可。</p><p><img src="https://itsfoss.com/content/images/2023/06/fzf-cd-combo.svg" alt="使用 fzf 命令结合 cd 命令进入任意目录"></p><h4 id="将选择内容复制到剪贴板" tabindex="-1">将选择内容复制到剪贴板 <a class="header-anchor" href="#将选择内容复制到剪贴板" aria-label="Permalink to “将选择内容复制到剪贴板”">​</a></h4><p>到目前为止，你已经了解了如何使用 <code>fzf</code>，它提供了搜索结果或预览。</p><p>现在，如果你想要复制某个项目的位置，你不必手动执行此操作。也有相应的解决方案。</p><p>首先，确保你已经安装了 <code>xclip</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install xclip</span></span></code></pre></div><p>然后像这样将其传递给 <code>xclip</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fzf | xclip -selection clipboard</span></span></code></pre></div><p>这将复制你按下回车键的那些行到剪贴板上。</p><h4 id="其他用途" tabindex="-1">其他用途 <a class="header-anchor" href="#其他用途" aria-label="Permalink to “其他用途”">​</a></h4><p>正如我之前所说，你可以使用任何涉及大量文本，并希望交互式搜索特定内容的命令。</p><ul><li><code>cat ~/.bashrc | fzf</code> - 在 Bashrc 文件中搜索</li><li><code>lsblk | fzf</code> - 在锁定设备列表中搜索</li><li><code>ps -aux | fzf</code> - 在进程列表中搜索</li></ul><h3 id="另一个选择-fzy-模糊选择器" tabindex="-1">另一个选择：Fzy，模糊选择器 <a class="header-anchor" href="#另一个选择-fzy-模糊选择器" aria-label="Permalink to “另一个选择：Fzy，模糊选择器”">​</a></h3><p>与 <code>fzf</code> 不同，<code>fzy</code> 是一个模糊选择器，它会根据输入提供一个菜单供你选择。</p><p>例如，如果你将 <code>fzy</code> 与 <code>ls</code> 命令一起使用，它将给你提供一个类似菜单的界面。</p><p><img src="https://itsfoss.com/content/images/2023/06/fzy-ls.svg" alt="使用 ls 命令的 fzy 命令"></p><p>默认情况下，它会显示十个条目。</p><h4 id="使用-fzy-进入目录" tabindex="-1">使用 fzy 进入目录 <a class="header-anchor" href="#使用-fzy-进入目录" aria-label="Permalink to “使用 fzy 进入目录”">​</a></h4><p>与 <code>fzf</code> 类似，你也可以使用 <code>fzy</code> 进入当前工作目录中的目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd $(find -type d | fzy)</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/06/fzy-cd.svg" alt=""></p><h4 id="使用任何编辑器打开文件" tabindex="-1">使用任何编辑器打开文件 <a class="header-anchor" href="#使用任何编辑器打开文件" aria-label="Permalink to “使用任何编辑器打开文件”">​</a></h4><p>或者使用你喜欢的编辑器打开文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nano $(find -type f | fzy)</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/06/fzy-nano.svg" alt=""></p><h3 id="附加内容-自定义文件和图像预览" tabindex="-1">附加内容：自定义文件和图像预览 <a class="header-anchor" href="#附加内容-自定义文件和图像预览" aria-label="Permalink to “附加内容：自定义文件和图像预览”">​</a></h3><p>下面的命令将在 <strong>Ubuntu</strong> 中打开一个专门的自定义提示符，用于模糊搜索，你可以通过滚动来预览文本文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /home/$USER -type f | fzf --color=&quot;bg:black,fg:yellow&quot; --preview &#39;batcat --color always {}&#39; --preview-window=bottom</span></span></code></pre></div><p>为了方便访问，可以在你的 <code>bashrc</code> 文件中为此创建一个别名。</p><p>或者在使用 <code>timg</code> 命令行图像查看器时，在 <code>fzf</code> 中进行图像预览并滚动。使用以下命令进行安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install timg</span></span></code></pre></div><blockquote><p>🚧 请注意，图像查看器无法正确显示图像，因为这不是 <code>fzf</code> 预览的主要目的。</p></blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fzf --preview &#39;timg -g 200x100 {}&#39; --preview-window=right:90</span></span></code></pre></div><p>对于那些喜欢折腾的人，可以尝试对此部分进行优化。</p><h3 id="现代化的替代方案" tabindex="-1">现代化的替代方案 <a class="header-anchor" href="#现代化的替代方案" aria-label="Permalink to “现代化的替代方案”">​</a></h3><p>大多数 Linux 命令都是从 UNIX 时代继承下来的。它们虽然老旧，但功能如预期。但这并不意味着它们不能改进。</p><p>我的意思是，你不需要重新发明轮子，但你总是可以努力改进轮子。</p><p>像 <code>fzf</code> 和 <code>fzy</code> 这样的现代化工具将 Linux 终端中的文件搜索提升到了一个新的水平。以下是一些其他有趣的命令行工具。</p><p>我尝试给出了这些模糊搜索工具的一些实际示例。希望你对它们感到足够有启发性。如果你打算使用它们，请在评论中告诉我。</p><p><em>（题图：MJ/d25e71fa-f24e-49be-9579-e0520a8f6e18）</em></p><hr>',45)),i("p",null,[s[14]||(s[14]=e("via: ",-1)),t(a,{href:"https://itsfoss.com/fuzzy-file-search-linux/"},{default:l(()=>[...s[13]||(s[13]=[e("https://itsfoss.com/fuzzy-file-search-linux/",-1)])]),_:1})]),i("p",null,[s[18]||(s[18]=e("作者：",-1)),t(a,{href:"https://itsfoss.com/author/sreenath/"},{default:l(()=>[...s[15]||(s[15]=[e("Sreenath",-1)])]),_:1}),s[19]||(s[19]=e(" 选题：",-1)),t(a,{href:"https://github.com/lkxed/"},{default:l(()=>[...s[16]||(s[16]=[e("lkxed",-1)])]),_:1}),s[20]||(s[20]=e(" 译者：ChatGPT 校对：",-1)),t(a,{href:"https://github.com/wxy"},{default:l(()=>[...s[17]||(s[17]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[23]||(s[23]=e("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[21]||(s[21]=[e("LCTT",-1)])]),_:1}),s[24]||(s[24]=e(" 原创编译，",-1)),t(a,{href:"https://linux.cn/"},{default:l(()=>[...s[22]||(s[22]=[e("Linux中国",-1)])]),_:1}),s[25]||(s[25]=e(" 荣誉推出",-1))])])}const x=o(h,[["render",f]]);export{y as __pageData,x as default};
